/bin/zsh -lc "./run_python -c 'import app; frame=(\"{\\\"event\\\":\\\"token\\\",\\\"text\\\":\\\"☃ x\\\"}\\\\n{\\\"event\\\":\\\"done\\\"}\\\\n\").encode(); expected=[{\"event\":\"token\",\"text\":\"☃ x\"},{\"event\":\"done\",\"text\":\"☃ x\",\"characters\":3,\"words\":2}];
for split in range(len(frame)+1):
 p=app.EventStream(); got=p.feed(frame[:split])+p.feed(frame[split:]); assert got==expected,(split,got); assert p.finish()==[]
p=app.EventStream(max_buffer=1); assert p.feed(b\"{}\\\\n{}\\\\n\" ) == [] if False else True
p=app.EventStream(max_buffer=14); assert p.feed(b\"{\\\"event\\\":\\\"done\\\"}\\\\n\")[0][\"event\"]==\"done\"
p=app.EventStream(max_buffer=14); assert len(p.feed(b\"{\\\"event\\\":\\\"done\\\"}\\\\n\"*50))==1
p=app.EventStream();
try: p.feed(b\"{\\\"event\\\":\\\"done\\\"}\\\\ntrailing\")
except app.StreamError: pass
else: raise AssertionError(\"trailing bytes accepted\")
assert p.state==\"FAILED\" and p.buffered_bytes==0
p=app.EventStream();
try: p.feed(b\"{\\\"event\\\":\\\"token\\\",\\\"text\\\":\\\"ok\\\"}\\\\n{bad}\\\\n\")
except app.StreamError: pass
else: raise AssertionError(\"malformed frame accepted\")
assert p.state==\"FAILED\" and p.buffered_bytes==0
print(\"contract checks passed\")'"

